import { useEffect, useRef } from 'react';

export default function VideoPlayer({ src, isPlaying }: {
  src: string;
  isPlaying: boolean;
}) {
  const videoRef = useRef<HTMLVideoElement>(null);

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;
    if (isPlaying) video.play();
    else video.pause();
  }, [isPlaying]);

  return <video ref={videoRef} src={src} controls />;
}

import { createContext, useContext, useReducer } from 'react';

type Task = { id: number; text: string };
type Action = { type: 'added'; text: string };

function reducer(tasks: Task[], action: Action): Task[] {
  if (action.type === 'added') {
    return [...tasks, { id: Date.now(), text: action.text }];
  }
  return tasks;
}

const TasksContext = createContext<Task[]>([]);
const TasksDispatchContext = createContext<React.Dispatch<Action>>(() => {});

function TaskProvider({ children }: { children: React.ReactNode }) {
  const [tasks, dispatch] = useReducer(reducer, []);
  return <TasksContext value={tasks}><TasksDispatchContext value={dispatch}>{children}</TasksDispatchContext></TasksContext>;
}

function AddTask() {
  const dispatch = useContext(TasksDispatchContext);
  return <button onClick={() => dispatch({ type: 'added', text: 'Read docs' })}>Add</button>;
}

